// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Line) predicate.Line {
	return predicate.Line(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Line) predicate.Line {
	return predicate.Line(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Line) predicate.Line {
	return predicate.Line(sql.NotPredicates(p))
}
